import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    query = [int(next(it)) for _ in range(n)]

    cost = 0
    available = set()
    access = [0] * 81
    for book in query:
        access[book] += 1
    removable = -1

    for i in range(n):
        current = query[i]
        does_not_contain = current not in available
        if does_not_contain:
            cost += 1

        if removable != -1:
            available.remove(removable)
            removable = -1
        elif len(available) == k and does_not_contain:
            removable_book = -1
            count = k
            known = set()
            for j in range(i + 1, n):
                if count <= 0:
                    break
                book = query[j]
                if book in available and book not in known:
                    count -= 1
                    known.add(book)
                    removable_book = book
            if removable_book != -1:
                available.remove(removable_book)
            else:
                available.remove(next(iter(available)))

        available.add(current)
        access[current] -= 1
        if access[current] == 0:
            removable = current

    sys.stdout.write(str(cost))

if __name__ == "__main__":
    solve()

